calls.reply:
"player": "Vasha",
 "characters": [
   {
     "name": "Elder Marfa of Novogorod",
     "world": true,
     "facts": "The Chair of the Council of Elders, a former scholar of tremendous learning. She has held the position since 1018 and is known for her measured temperament and deep knowledge of pre-Sovanie texts."
   },
   {
     "name": "Brother Andronik",
     "world": false,
     "heritage": "Owl-folk",
     "facts": "A young cleric assigned as attendant to the Hall of Lanterns, barely twenty years old. He is earnest and slightly nervous around senior couriers, eager to prove himself useful. His plumage is pale grey with a white breast, and his large eyes blink rapidly when he is anxious."
   }
 ],
 "place": {
   "name": "Hall of Lanterns",
   "world": true,
   "facts": "The chamber within the Amber Palace where the Council of Elders convenes. It is lit by hundreds of amber-lanterns that cast a warm, honeyed glow. The hall has high vaulted ceilings and arched windows facing east, so that the first light of dawn spills across the stone floor in long golden bands."
 },
 "extras": [
   {
     "name": "The Dawn Vigil Congregation",
     "facts": "A gathering of dozens of faithful Sovy filling the adjacent nave of the Amber Palace chapel, their soft wing-feathers rustling as they kneel and rise in unison. Many are parish clergy, some are courtiers, and a few are common folk who have traveled to the capital for the Council session."
   }
 ],
 "goal": "Vasha arrives at the Hall of Lanterns before dawn with a sealed letter that must reach the Council of Elders before the morning's business concludes, and she must navigate both the physical and political geography of the Amber Palace to deliver it.",
 "intro": "The sky above Velikigorod is the color of a bruise — deep purple fading to black along the western horizon — when Vasha's taloned feet touch the stone ledge of the Amber Palace's eastern colonnade. The palace rises before her like a great amber tooth set into the riverbank, its towers and spires catching the last starlight. She has made the flight from Veliky Ustyug in under six hours, gliding from bell-tower to bell-tower through the predawn dark, her internal map of the diocesan network clicking into place with each known landmark. The leather satchel at her chest is warm from her body heat, and inside it the sealed letter presses against her breastbone like a second heartbeat. The seal is the Archpriest's own — a sunburst stamped in black wax — and the letter is addressed to the Council of Elders in care of Elder Marfa. She does not know what it says. She was told only that it must arrive before the Council's morning session ends, and that she must deliver it personally and to no other hand. The colonnade is cold under her feet. Below, the rivers Mstara and Volkhova whisper against their banks, and somewhere in the chapel beneath her, she can hear the first low notes of the Dawn Vigil beginning — the ancient hymn to Saint Ilarion, its melody threading upward through the stone like smoke." }

