calls.reply:
"player": "Vasha",
 "characters": [
   {
     "name": "Elder Marfa of Novogorod",
     "world": true,
     "facts": "The Chair of the Council of Elders, a former scholar of tremendous learning who has held the position since 1018. She is known for her measured temperament and her unyielding commitment to the Doctrine of Transcendence."
   },
   {
     "name": "Brother Ananai",
     "world": false,
     "heritage": "Owl-folk",
     "facts": "A young acolyte assigned to the Hall of Lanterns this morning as a junior attendant. He is barely twenty and clearly nervous about his first formal service in the Council chamber, fidgeting with the hem of his vestments and glancing toward the door every few moments."
   }
 ],
 "place": {
   "name": "Hall of Lanterns",
   "world": true,
   "facts": "The chamber within the Amber Palace where the Council of Elders convenes. At dawn, the hundreds of amber-lanterns are lit one by one by acolytes, filling the room with a warm, honeyed glow that seems to thicken the air itself."
 },
 "extras": [
   {
     "name": "The Dawn Vigil congregation",
     "facts": "A modest gathering of clergy, acolytes, and lay faithful who have come early to observe the Vigil in the Amber Palace's main nave before the Council session begins. They murmur among themselves in low, reverent tones, their wings folded close to their bodies in the traditional posture of prayerful attentiveness."
   }
 ],
 "goal": "Vasha must deliver a sealed letter to the Council of Elders during the Dawn Vigil, navigating the tension between her duty as a Church courier and her private skepticism about the theology she serves.",
 "intro": "The first light of dawn spills through the arched windows of the Amber Palace like poured honey, and the Hall of Lanterns begins to glow from within as acolytes move between the pillars, touching flame to wick after wick. The amber lanterns bloom one by one — dozens, then hundreds — until the chamber hums with a warm radiance that makes the stone walls look like sunlit amber. Outside, the bells of Velikigorod's parish churches have just begun their dawn chorus, a cascade of deep, resonant tones rolling across the river valleys and through the high-walled corridors of the capital city. The Sovy faithful are gathering in every church, in every village, in every field lantern-lit farmstead across the Tsardom, turning their faces toward the east as they have done every morning for sixteen years. Inside the Hall of Lanterns, the Dawn Vigil is already underway — a handful of clergy stand at the front of the chamber in the traditional prayer stance, their wings pressed gently against their backs, their voices weaving through the ancient liturgy of the Church of the Divine Sovanie. Vasha stands near the entrance, her russet-brown plumage catching the lantern-light, her amber-gold eyes scanning the room with the quiet precision of someone who has mapped a hundred such spaces in her mind. The leather satchel at her side bears the sunburst emblem of the Church, and within it, a sealed letter that has traveled from the eastern border to the heart of the Tsardom — a letter meant for the Council of Elders and the Elder Chair herself. She waits, patient as a night wind, for the Vigil to reach its natural pause." }

